* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* ==========================================================================
   SISTEMA DE CONTROLE DE ACESSO — ENTERPRISE SECURITY DESIGN SYSTEM
   Baseado em IBM Carbon, Microsoft Fluent UI e Dashboards de Cibersegurança
   Paleta: Dark Navy (#0B1220 / #0F172A / #111827 / #1E293B)
   ========================================================================== */

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    min-height: 100vh;
    color: white;
    line-height: 1.6;
}

/* --------------------------------------------------------------------------
   1. TOKENS DO DESIGN SYSTEM
   -------------------------------------------------------------------------- */
:root {
    /* Cores de Fundo e Superfícies */
    --bg-main: #0B1220;
    --bg-sidebar: #0F172A;
    --bg-card: #111827;
    --bg-card-hover: #162032;
    --bg-surface: #1E293B;
    --bg-surface-hover: #26354D;
    --bg-input: #0F172A;
    --bg-modal-overlay: rgba(11, 18, 32, 0.85);

    .login-container {
        min-height: 100vh;
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 2rem;
    }

    /* Cores Primárias e Semânticas */
    --color-primary: #2563EB;
    --color-primary-hover: #1D4ED8;
    --color-primary-subtle: rgba(37, 99, 235, 0.15);

    .login-card {
        background: rgba(255, 255, 255, 0.15);
        backdrop-filter: blur(20px);
        border: 1px solid rgba(255, 255, 255, 0.25);
        border-radius: 20px;
        padding: 40px;
        box-shadow: 0 20px 40px rgba(102, 126, 234, 0.4);
        min-width: 400px;
        text-align: center;
    }

    --color-cyan: #06B6D4;
    --color-cyan-hover: #0891B2;
    --color-cyan-subtle: rgba(6, 182, 212, 0.15);

    .logo {
        font-size: 48px;
        margin-bottom: 10px;
    }

    --color-success: #10B981;
    --color-success-hover: #059669;
    --color-success-subtle: rgba(16, 185, 129, 0.15);

    .login-card h1 {
        margin-bottom: 10px;
        font-weight: 300;
        font-size: 28px;
    }

    --color-error: #EF4444;
    --color-error-hover: #DC2626;
    --color-error-subtle: rgba(239, 68, 68, 0.15);

    .subtitle {
        opacity: 0.8;
        margin-bottom: 40px;
        font-size: 16px;
    }

    --color-warning: #F59E0B;
    --color-warning-hover: #D97706;
    --color-warning-subtle: rgba(245, 158, 11, 0.15);

    .form-group {
        margin-bottom: 20px;
        text-align: left;
    }

    /* Tipografia e Texto */
    --text-primary: #F8FAFC;
    --text-secondary: #94A3B8;
    --text-muted: #64748B;
    --text-inverse: #0B1220;

    .form-group label {
        display: block;
        margin-bottom: 8px;
        font-size: 14px;
        opacity: 0.9;
    }

    /* Bordas */
    --border-color: #334155;
    --border-subtle: #1E293B;
    --border-focus: #2563EB;

    .form-group input {
        width: 100%;
        padding: 15px;
        border: 1px solid rgba(255, 255, 255, 0.3);
        border-radius: 10px;
        font-size: 16px;
        background: rgba(255, 255, 255, 0.1);
        color: white;
        backdrop-filter: blur(10px);
    }

    /* Tipografia */
    --font-family: 'Inter',
    -apple-system,
    BlinkMacSystemFont,
    'Segoe UI',
    Roboto,
    Helvetica,
    Arial,
    sans-serif;
    --font-mono: 'JetBrains Mono',
    'Fira Code',
    'Courier New',
    monospace;

    .form-group input::placeholder {
        color: rgba(255, 255, 255, 0.7);
    }

    /* Raios de Borda */
    --radius-sm: 4px;
    --radius-md: 6px;
    --radius-lg: 8px;
    --radius-xl: 12px;
    --radius-2xl: 16px;
    --radius-full: 9999px;

    .form-group input:focus {
        outline: none;
        border-color: rgba(255, 255, 255, 0.6);
        background: rgba(255, 255, 255, 0.2);
        box-shadow: 0 0 0 3px rgba(118, 75, 162, 0.3);
    }

    /* Sombras Corporativas */
    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.4);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.5),
    0 2px 4px -2px rgba(0, 0, 0, 0.3);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.6),
    0 4px 6px -4px rgba(0, 0, 0, 0.4);
    --shadow-card: 0 4px 16px rgba(0, 0, 0, 0.35);

    .login-btn {
        width: 100%;
        padding: 15px;
        background: linear-gradient(135deg, #764ba2 0%, #667eea 100%);
        color: white;
        border: none;
        border-radius: 10px;
        font-size: 16px;
        cursor: pointer;
        transition: all 0.3s ease;
        backdrop-filter: blur(10px);
        margin-top: 20px;
        box-shadow: 0 8px 20px rgba(118, 75, 162, 0.4);
        /* Transições */
        --transition-fast: 0.15s ease;
        --transition-normal: 0.25s ease;
    }

    .login-btn:hover {
        background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
        transform: translateY(-2px);
        box-shadow: 0 12px 30px rgba(118, 75, 162, 0.6);

        /* --------------------------------------------------------------------------
   2. RESET E ESTILOS GLOBAIS
   -------------------------------------------------------------------------- */
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        .error-message {
            background: rgba(255, 0, 0, 0.8);
            color: white;
            padding: 10px;
            border-radius: 5px;
            margin-top: 15px;

            html,
            body {
                height: 100%;
            }

            .login-info {
                margin-top: 30px;
                padding: 20px;
                background: rgba(0, 0, 0, 0.1);
                border-radius: 10px;

                body {
                    font-family: var(--font-family);
                    background-color: var(--bg-main);
                    color: var(--text-primary);
                    line-height: 1.5;
                    font-size: 14px;
                    -webkit-font-smoothing: antialiased;
                    -moz-osx-font-smoothing: grayscale;
                    overflow-x: hidden;
                }

                .login-info h4 {
                    margin-bottom: 10px;
                    color: #e0aaff;
                    font-weight: 600;

                    /* Scrollbars corporativas escuras */
                    ::-webkit-scrollbar {
                        width: 6px;
                        height: 6px;
                    }

                    .login-info p {
                        margin: 5px 0;
                        font-size: 14px;
                        opacity: 0.9;

                        ::-webkit-scrollbar-track {
                            background: var(--bg-main);
                        }

                        .dashboard-container {
                            padding: 20px;
                            max-width: 1200px;
                            margin: 0 auto;

                            ::-webkit-scrollbar-thumb {
                                background: var(--border-color);
                                border-radius: var(--radius-full);
                            }

                            .sidebar {
                                position: fixed;
                                top: 0;
                                left: -300px;
                                width: 300px;
                                height: 100vh;
                                background: rgba(255, 255, 255, 0.1);
                                backdrop-filter: blur(20px);
                                border-right: 1px solid rgba(255, 255, 255, 0.2);
                                transition: left 0.3s ease;
                                z-index: 1000;
                                display: flex;
                                flex-direction: column;

                                ::-webkit-scrollbar-thumb:hover {
                                    background: var(--text-muted);
                                }

                                .sidebar.active {
                                    left: 0;

                                    a {
                                        color: var(--color-cyan);
                                        text-decoration: none;
                                        transition: color var(--transition-fast);
                                    }

                                    .sidebar-header {
                                        padding: 20px;
                                        border-bottom: 1px solid rgba(255, 255, 255, 0.1);
                                        display: flex;
                                        justify-content: space-between;
                                        align-items: center;

                                        a:hover {
                                            color: var(--color-primary);
                                        }

                                        .sidebar-logo {
                                            display: flex;
                                            align-items: center;
                                            gap: 10px;
                                            font-size: 18px;
                                            font-weight: 600;
                                        }

                                        .close-sidebar {
                                            background: none;

                                            button {
                                                font-family: inherit;
                                                cursor: pointer;
                                                border: none;
                                                color: white;
                                                font-size: 18px;
                                                cursor: pointer;
                                                padding: 5px;
                                                border-radius: 5px;
                                                transition: background 0.3s ease;
                                                outline: none;
                                            }

                                            .close-sidebar:hover {
                                                background: rgba(255, 255, 255, 0.1);

                                                input,
                                                select,
                                                textarea {
                                                    font-family: inherit;
                                                    font-size: 14px;
                                                }

                                                .sidebar-nav {
                                                    flex: 1;
                                                    padding: 20px 0;

                                                    /* --------------------------------------------------------------------------
   3. TELA DE LOGIN
   -------------------------------------------------------------------------- */
                                                    .login-container {
                                                        min-height: 100vh;
                                                        display: flex;
                                                        flex-direction: column;
                                                        align-items: center;
                                                        justify-content: center;
                                                        padding: 2rem;
                                                        background-color: var(--bg-main);
                                                        background-image:
                                                            radial-gradient(ellipse 60% 50% at 50% 20%, rgba(37, 99, 235, 0.12), transparent 70%),
                                                            radial-gradient(circle at 80% 80%, rgba(6, 182, 212, 0.08), transparent 50%),
                                                            linear-gradient(to right, rgba(30, 41, 59, 0.15) 1px, transparent 1px),
                                                            linear-gradient(to bottom, rgba(30, 41, 59, 0.15) 1px, transparent 1px);
                                                        background-size: 100% 100%, 100% 100%, 40px 40px, 40px 40px;
                                                        position: relative;
                                                    }

                                                    .nav-item-dropdown {
                                                        .login-card {
                                                            width: 100%;
                                                            max-width: 440px;
                                                            background: var(--bg-card);
                                                            border: 1px solid var(--border-color);
                                                            border-radius: var(--radius-2xl);
                                                            padding: 40px 36px 36px 36px;
                                                            box-shadow: 0 20px 40px -15px rgba(0, 0, 0, 0.7), 0 0 30px -10px rgba(37, 99, 235, 0.2);
                                                            text-align: center;
                                                            position: relative;
                                                            z-index: 1;
                                                        }

                                                        .nav-item {
                                                            .login-shield-badge {
                                                                width: 68px;
                                                                height: 68px;
                                                                margin: 0 auto 20px;
                                                                background: linear-gradient(135deg, rgba(37, 99, 235, 0.2) 0%, rgba(6, 182, 212, 0.25) 100%);
                                                                border: 1px solid rgba(6, 182, 212, 0.4);
                                                                border-radius: var(--radius-xl);
                                                                display: flex;
                                                                align-items: center;
                                                                gap: 15px;
                                                                padding: 15px 20px;
                                                                color: white;
                                                                text-decoration: none;
                                                                transition: all 0.3s ease;
                                                                border-left: 3px solid transparent;
                                                                position: relative;
                                                                justify-content: center;
                                                                box-shadow: 0 8px 20px rgba(6, 182, 212, 0.25);
                                                            }

                                                            .nav-item-parent {
                                                                justify-content: space-between;

                                                                .login-shield-badge i {
                                                                    font-size: 32px;
                                                                    color: var(--color-cyan);
                                                                    filter: drop-shadow(0 0 8px rgba(6, 182, 212, 0.5));
                                                                }

                                                                .dropdown-arrow {
                                                                    font-size: 12px;
                                                                    transition: transform 0.3s ease;
                                                                    margin-left: auto;

                                                                    .login-card h1 {
                                                                        font-size: 22px;
                                                                        font-weight: 600;
                                                                        color: var(--text-primary);
                                                                        letter-spacing: -0.02em;
                                                                        margin-bottom: 6px;
                                                                    }

                                                                    .nav-item-parent.active .dropdown-arrow {
                                                                        transform: rotate(180deg);

                                                                        .login-card .subtitle {
                                                                            font-size: 13.5px;
                                                                            color: var(--text-secondary);
                                                                            margin-bottom: 28px;
                                                                            font-weight: 400;
                                                                        }

                                                                        .nav-submenu {
                                                                            max-height: 0;
                                                                            overflow: hidden;
                                                                            transition: max-height 0.3s ease;
                                                                            background: rgba(0, 0, 0, 0.1);

                                                                            .login-form .form-group {
                                                                                margin-bottom: 18px;
                                                                                text-align: left;
                                                                            }

                                                                            .nav-submenu.active {
                                                                                max-height: 200px;
                                                                            }

                                                                            .nav-subitem {
                                                                                .login-form label {
                                                                                    display: flex;
                                                                                    align-items: center;
                                                                                    gap: 15px;
                                                                                    padding: 12px 20px 12px 50px;
                                                                                    color: rgba(255, 255, 255, 0.9);
                                                                                    text-decoration: none;
                                                                                    transition: all 0.3s ease;
                                                                                    border-left: 3px solid transparent;
                                                                                    font-size: 14px;
                                                                                    gap: 8px;
                                                                                    font-size: 13px;
                                                                                    font-weight: 500;
                                                                                    color: var(--text-secondary);
                                                                                    margin-bottom: 8px;
                                                                                }

                                                                                .nav-subitem:hover {
                                                                                    background: rgba(255, 255, 255, 0.1);
                                                                                    border-left-color: rgba(255, 255, 255, 0.5);
                                                                                    color: white;

                                                                                    .login-form label i {
                                                                                        font-size: 13px;
                                                                                        color: var(--text-muted);
                                                                                    }

                                                                                    .nav-subitem.active {
                                                                                        background: rgba(255, 255, 255, 0.15);
                                                                                        border-left-color: #f1c40f;
                                                                                        color: white;

                                                                                        .input-with-icon {
                                                                                            position: relative;
                                                                                            display: flex;
                                                                                            align-items: center;
                                                                                        }

                                                                                        .nav-item:hover {
                                                                                            background: rgba(255, 255, 255, 0.1);
                                                                                            border-left-color: rgba(255, 255, 255, 0.5);

                                                                                            .input-with-icon input {
                                                                                                width: 100%;
                                                                                                padding: 12px 14px;
                                                                                                background: var(--bg-input);
                                                                                                border: 1px solid var(--border-color);
                                                                                                border-radius: var(--radius-lg);
                                                                                                color: var(--text-primary);
                                                                                                font-size: 14px;
                                                                                                transition: all var(--transition-fast);
                                                                                            }

                                                                                            .nav-item.active {
                                                                                                background: rgba(255, 255, 255, 0.15);
                                                                                                border-left-color: #f1c40f;

                                                                                                .input-with-icon input:focus {
                                                                                                    outline: none;
                                                                                                    border-color: var(--color-primary);
                                                                                                    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.25);
                                                                                                    background: #0B1324;
                                                                                                }

                                                                                                .nav-item i {
                                                                                                    font-size: 18px;
                                                                                                    width: 20px;
                                                                                                    text-align: center;

                                                                                                    .input-with-icon input::placeholder {
                                                                                                        color: var(--text-muted);
                                                                                                    }

                                                                                                    .nav-subitem i {
                                                                                                        font-size: 16px;
                                                                                                        width: 18px;
                                                                                                        text-align: center;

                                                                                                        .password-toggle-btn {
                                                                                                            position: absolute;
                                                                                                            right: 12px;
                                                                                                            background: transparent;
                                                                                                            color: var(--text-muted);
                                                                                                            font-size: 14px;
                                                                                                            padding: 6px;
                                                                                                            border-radius: var(--radius-sm);
                                                                                                            transition: color var(--transition-fast);
                                                                                                        }

                                                                                                        .sidebar-footer {
                                                                                                            padding: 20px;
                                                                                                            border-top: 1px solid rgba(255, 255, 255, 0.1);

                                                                                                            .password-toggle-btn:hover {
                                                                                                                color: var(--text-primary);
                                                                                                            }

                                                                                                            .user-profile {
                                                                                                                .login-btn {
                                                                                                                    width: 100%;
                                                                                                                    margin-top: 10px;
                                                                                                                    padding: 13px 20px;
                                                                                                                    background: var(--color-primary);
                                                                                                                    color: #FFFFFF;
                                                                                                                    font-size: 14.5px;
                                                                                                                    font-weight: 600;
                                                                                                                    border-radius: var(--radius-lg);
                                                                                                                    display: flex;
                                                                                                                    align-items: center;
                                                                                                                    gap: 12px;
                                                                                                                }

                                                                                                                .user-avatar {
                                                                                                                    width: 40px;
                                                                                                                    height: 40px;
                                                                                                                    background: linear-gradient(135deg, #e0aaff 0%, #c77dff 100%);
                                                                                                                    border-radius: 50%;
                                                                                                                    display: flex;
                                                                                                                    align-items: center;
                                                                                                                    justify-content: center;
                                                                                                                    font-size: 16px;
                                                                                                                    color: white;
                                                                                                                    gap: 10px;
                                                                                                                    transition: all var(--transition-fast);
                                                                                                                    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.35);
                                                                                                                }

                                                                                                                .user-info {
                                                                                                                    display: flex;
                                                                                                                    flex-direction: column;

                                                                                                                    .login-btn:hover {
                                                                                                                        background: var(--color-primary-hover);
                                                                                                                        box-shadow: 0 6px 16px rgba(37, 99, 235, 0.5);
                                                                                                                        transform: translateY(-1px);
                                                                                                                    }

                                                                                                                    .user-name {
                                                                                                                        font-weight: 600;
                                                                                                                        font-size: 14px;

                                                                                                                        .login-btn:active {
                                                                                                                            transform: translateY(0);
                                                                                                                        }

                                                                                                                        .user-role {
                                                                                                                            font-size: 12px;
                                                                                                                            opacity: 0.7;

                                                                                                                            .login-btn:focus-visible {
                                                                                                                                outline: 2px solid var(--color-cyan);
                                                                                                                                outline-offset: 2px;
                                                                                                                            }

                                                                                                                            .sidebar-overlay {
                                                                                                                                position: fixed;
                                                                                                                                top: 0;
                                                                                                                                left: 0;
                                                                                                                                width: 100%;
                                                                                                                                height: 100%;
                                                                                                                                background: rgba(0, 0, 0, 0.5);
                                                                                                                                opacity: 0;
                                                                                                                                visibility: hidden;
                                                                                                                                transition: all 0.3s ease;
                                                                                                                                z-index: 999;
                                                                                                                            }

                                                                                                                            .sidebar-overlay.active {
                                                                                                                                opacity: 1;
                                                                                                                                visibility: visible;
                                                                                                                            }

                                                                                                                            .modal-overlay {
                                                                                                                                position: fixed;
                                                                                                                                top: 0;
                                                                                                                                left: 0;
                                                                                                                                width: 100%;
                                                                                                                                height: 100%;
                                                                                                                                background: rgba(0, 0, 0, 0.6);
                                                                                                                                backdrop-filter: blur(5px);

                                                                                                                                .error-message {
                                                                                                                                    margin-top: 16px;
                                                                                                                                    padding: 11px 14px;
                                                                                                                                    background: var(--color-error-subtle);
                                                                                                                                    border: 1px solid rgba(239, 68, 68, 0.35);
                                                                                                                                    border-radius: var(--radius-md);
                                                                                                                                    color: var(--color-error);
                                                                                                                                    font-size: 13px;
                                                                                                                                    font-weight: 500;
                                                                                                                                    display: flex;
                                                                                                                                    align-items: center;
                                                                                                                                    justify-content: center;
                                                                                                                                    opacity: 0;
                                                                                                                                    visibility: hidden;
                                                                                                                                    transition: all 0.3s ease;
                                                                                                                                    z-index: 9999;
                                                                                                                                    gap: 8px;
                                                                                                                                    text-align: left;
                                                                                                                                }

                                                                                                                                .modal-overlay.active {
                                                                                                                                    opacity: 1;
                                                                                                                                    visibility: visible;

                                                                                                                                    .login-footer-tagline {
                                                                                                                                        margin-top: 24px;
                                                                                                                                        font-size: 12.5px;
                                                                                                                                        color: var(--text-muted);
                                                                                                                                        letter-spacing: 0.05em;
                                                                                                                                        font-weight: 500;
                                                                                                                                    }

                                                                                                                                    #modalOverlay {
                                                                                                                                        z-index: 10000;

                                                                                                                                        /* --------------------------------------------------------------------------
   4. LAYOUT PRINCIPAL DO DASHBOARD
   -------------------------------------------------------------------------- */
                                                                                                                                        .dashboard-container {
                                                                                                                                            display: flex;
                                                                                                                                            min-height: 100vh;
                                                                                                                                            background-color: var(--bg-main);
                                                                                                                                            position: relative;
                                                                                                                                        }

                                                                                                                                        .modal-container {
                                                                                                                                            background: rgba(255, 255, 255, 0.15);
                                                                                                                                            backdrop-filter: blur(25px);
                                                                                                                                            border: 1px solid rgba(255, 255, 255, 0.3);
                                                                                                                                            border-radius: 20px;
                                                                                                                                            min-width: 400px;
                                                                                                                                            max-width: 500px;
                                                                                                                                            padding: 0;
                                                                                                                                            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.3);
                                                                                                                                            transform: scale(0.9);
                                                                                                                                            transition: transform 0.3s ease;

                                                                                                                                            /* SIDEBAR */
                                                                                                                                            .sidebar {
                                                                                                                                                width: 260px;
                                                                                                                                                min-width: 260px;
                                                                                                                                                background-color: var(--bg-sidebar);
                                                                                                                                                border-right: 1px solid var(--border-subtle);
                                                                                                                                                display: flex;
                                                                                                                                                flex-direction: column;
                                                                                                                                                justify-content: space-between;
                                                                                                                                                height: 100vh;
                                                                                                                                                position: sticky;
                                                                                                                                                top: 0;
                                                                                                                                                z-index: 40;
                                                                                                                                                transition: transform var(--transition-normal);
                                                                                                                                            }

                                                                                                                                            .modal-overlay.active .modal-container {
                                                                                                                                                transform: scale(1);

                                                                                                                                                .sidebar-header {
                                                                                                                                                    padding: 20px 20px 18px 20px;
                                                                                                                                                    display: flex;
                                                                                                                                                    align-items: center;
                                                                                                                                                    justify-content: space-between;
                                                                                                                                                    border-bottom: 1px solid var(--border-subtle);
                                                                                                                                                }

                                                                                                                                                .modal-header {
                                                                                                                                                    padding: 25px 30px 20px;
                                                                                                                                                    text-align: center;
                                                                                                                                                    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
                                                                                                                                                    position: relative;
                                                                                                                                                }

                                                                                                                                                .modal-header h3 {
                                                                                                                                                    color: white;
                                                                                                                                                    font-size: 20px;
                                                                                                                                                    font-weight: 600;
                                                                                                                                                    margin: 0;

                                                                                                                                                    .sidebar-brand {
                                                                                                                                                        display: flex;
                                                                                                                                                        align-items: center;
                                                                                                                                                        justify-content: center;
                                                                                                                                                        gap: 10px;
                                                                                                                                                        gap: 12px;
                                                                                                                                                        text-decoration: none;
                                                                                                                                                    }

                                                                                                                                                    .modal-close {
                                                                                                                                                        position: absolute;
                                                                                                                                                        top: 20px;
                                                                                                                                                        right: 20px;
                                                                                                                                                        background: none;
                                                                                                                                                        border: none;
                                                                                                                                                        color: rgba(255, 255, 255, 0.7);
                                                                                                                                                        font-size: 20px;
                                                                                                                                                        cursor: pointer;
                                                                                                                                                        transition: all 0.3s ease;
                                                                                                                                                        width: 35px;
