                                                                                                                                                                                                                                                                                                                                                                                                                                                                            font-weight: 500;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .areas-list {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            flex-direction: column;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            gap: 10px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            max-height: 300px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            overflow-y: auto;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            /* Indicador AO VIVO */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .status-live {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                display: inline-flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                align-items: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                gap: 6px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                font-size: 11.5px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                font-weight: 700;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                color: var(--color-success);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                letter-spacing: 0.05em;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding: 4px 8px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                background: rgba(16, 185, 129, 0.1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                border: 1px solid rgba(16, 185, 129, 0.3);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                border-radius: var(--radius-full);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .area-item {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                justify-content: space-between;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                align-items: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                background: rgba(255, 255, 255, 0.1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding: 15px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                border-radius: 8px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                border: 1px solid rgba(255, 255, 255, 0.1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                transition: all 0.3s ease;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .status-live-dot {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    width: 7px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    height: 7px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    background: var(--color-success);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    border-radius: var(--radius-full);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    box-shadow: 0 0 8px var(--color-success);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    animation: pulseDot 2s infinite;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .area-item:hover {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    background: rgba(255, 255, 255, 0.15);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    transform: translateY(-2px);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    @keyframes pulseDot {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        0% {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            transform: scale(0.9);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            opacity: 0.8;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        50% {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            transform: scale(1.3);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            opacity: 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        100% {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            transform: scale(0.9);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            opacity: 0.8;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .area-info .area-name {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        font-size: 14px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        font-weight: 600;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        color: white;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        margin-bottom: 5px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        /* TABELA DE ÁREAS MONITORADAS */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .areas-table-container {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            flex: 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            overflow-x: auto;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .area-details {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            gap: 15px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            font-size: 12px;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .areas-corp-table {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                width: 100%;
