                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    font-weight: 600;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    font-size: 11.5px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    text-transform: uppercase;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    font-size: 11px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    letter-spacing: 0.05em;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    border-bottom: 1px solid var(--border-subtle);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    background: rgba(15, 23, 42, 0.5);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .area-capacity {
