                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        vertical-align: middle;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .area-status {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        text-align: right;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .areas-corp-table tr:last-child td {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            border-bottom: none;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .status-active {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            background: #48bb78;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            color: white;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            padding: 4px 8px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            border-radius: 12px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            font-size: 11px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            font-weight: 600;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            text-transform: uppercase;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .areas-corp-table tr:hover td {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                background: var(--bg-card-hover);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .empty-state {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                text-align: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding: 40px 20px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                opacity: 0.7;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .area-name-cell {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    align-items: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    gap: 10px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    font-weight: 500;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    color: var(--text-primary);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .empty-state i {
