                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .badge-inactive {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                display: inline-flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                align-items: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                gap: 6px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding: 4px 10px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                background: rgba(148, 163, 184, 0.12);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                border: 1px solid rgba(148, 163, 184, 0.35);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                border-radius: var(--radius-full);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                color: #94A3B8;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                font-size: 11px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                font-weight: 700;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            /* FEED DE ACESSOS EM TEMPO REAL */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .access-feed {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                flex-direction: column;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                gap: 12px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                max-height: 400px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                gap: 10px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                max-height: 380px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                overflow-y: auto;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding-right: 5px;
